/* ═══════════════ TOKENS ═══════════════ */
:root {
  --g: #dda851;
  --n: #192b45;
  --gr: #ededed;
  --w: #fff;
  --g-rgb: 221, 168, 81;
  --n-rgb: 25, 43, 69;
  --ease: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
}

a {
  text-decoration: none !important;
}
body{
  margin:0;
  padding:0;
}
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: "Quicksand", sans-serif;
  background: var(--w);
  color: var(--n);
  overflow-x: hidden;
  cursor: none;
}
img {
  display: block;
  width: 100%;
  object-fit: cover;
}
a {
  text-decoration: none;
  color: inherit;
}
ul {
  list-style: none;
}

/* ═══════════════ CURSOR ═══════════════ */
#cur {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9999;
  width: 10px;
  height: 10px;
  background: var(--g);
  border-radius: 50%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition:
    width 0.3s,
    height 0.3s,
    opacity 0.3s;
  mix-blend-mode: exclusion;
}
#cur-ring {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9998;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(var(--g-rgb), 0.5);
  border-radius: 50%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition:
    width 0.5s var(--ease),
    height 0.5s var(--ease),
    border-color 0.3s;
}
.hovering #cur {
  width: 16px;
  height: 16px;
}
.hovering #cur-ring {
  width: 68px;
  height: 68px;
  border-color: rgba(var(--g-rgb), 0.8);
}

/* ═══════════════ NAV ═══════════════ */
nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 900;
  display: flex;
  align-items: center;
  justify-content: space-between;
  /* padding: 30px 64px; */
  padding-top: 30px;
  padding-bottom: 15px;
  padding-left: 64px;
  padding-right:64px;
  transition:
    padding 0.6s var(--ease),
    background 0.5s,
    box-shadow 0.5s;
}
nav.stuck {
  padding: 16px 64px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(24px);
  box-shadow: 0 1px 0 rgba(var(--n-rgb), 0.07);
}
.wm {
  display: flex;
  flex-direction: column;
  line-height: 1;
  text-decoration: none;
}
.wm-main {
  font-family: "League Spartan", sans-serif;
  font-size: 40px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--w);
  transition: color 0.4s;
}
.wm-main .dot {
  color: var(white);
}
.wm-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  margin-top: 3px;
  transition: color 0.4s;
}
nav.stuck .wm-main {
  color: var(--n);
}
nav.stuck .wm-sub {
  color: rgba(var(--n-rgb), 0.35);
}
.nav-links {
  display: flex;
  gap: 36px;
}
.nav-links a {
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.75);
  position: relative;
  transition: color 0.3s;
}
.nav-links a::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: 50%;
  width: 0;
  height: 1px;
  background: var(--g);
  transform: translateX(-50%);
  transition: width 0.4s var(--ease);
}
.nav-links a:hover,
.nav-links a.act {
  color: var(--g);
}
.nav-links a:hover::after,
.nav-links a.act::after {
  width: 100%;
}
nav.stuck .nav-links a {
  color: var(--n);
}
nav.stuck .nav-links a:hover {
  color: var(--g);
}
.ncta {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  background: var(--g); /* Normal yellow */
  padding: 11px 28px;
  border: 1px solid var(--g);
  color: var(--w);
  position: relative;
  overflow: hidden;
  transition:
    color 0.3s,
    border-color 0.3s,
    background 0.3s;
}

.ncta::before {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  transform: translateY(102%);
  transition: transform 0.45s var(--ease);
}

.ncta span {
  position: relative;
  z-index: 1;
}

.ncta:hover {
  background: transparent; /* Hover transparent */
  color: var(--w);
  border-color: rgba(255, 255, 255, 0.3);
}
.ncta:hover::before {
  transform: translateY(0);
}
nav.stuck .ncta {
  border-color: rgba(var(--n-rgb), 0.25);
  color: var(--n);
}
nav.stuck .ncta:hover {
  color: var(--n);
}
.ham {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: none;
  border: 0;
  background: transparent;
  padding: 6px;
}
.ham span {
  width: 22px;
  height: 1.5px;
  background: var(--w);
  display: block;
  transition: background 0.4s;
}
nav.stuck .ham span {
  background: var(--n);
}

/* Mobile left sidebar (hamburger) */
.mnav-backdrop {
  position: fixed;
  inset: 0;
  z-index: 905;
  background: rgba(0, 0, 0, 0.36);
  opacity: 0;
  transition: opacity 0.25s var(--ease-out);
}
.mnav {
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: min(360px, 88vw);
  z-index: 906;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(22px);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.18);
  transform: translateX(-104%);
  transition: transform 0.35s var(--ease);
  padding: 18px 18px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.mnav.is-open {
  transform: translateX(0);
}
.mnav-backdrop.is-open {
  opacity: 1;
}
body.mnav-open {
  overflow: hidden;
  touch-action: none;
}
.mnav-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.mnav-brand {
  display: flex;
  flex-direction: column;
  line-height: 1;
  text-align: left;
}
.mnav-logo {
  font-family: "League Spartan", sans-serif;
  font-size: 32px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--n);
}
.mnav-logo .dot {
  color: var(--g);
}
.mnav-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.45);
  margin-top: 3px;
}
.mnav-close {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  border: 1px solid rgba(var(--n-rgb), 0.12);
  background: rgba(255, 255, 255, 0.7);
  color: rgba(var(--n-rgb), 0.75);
  font-size: 26px;
  line-height: 1;
  cursor: none;
  pointer-events: auto;
}
.mnav-search {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid rgba(var(--n-rgb), 0.1);
  border-radius: 16px;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.65);
}
.mnav-search-ico {
  color: rgba(var(--n-rgb), 0.55);
  font-size: 14px;
  line-height: 1;
  user-select: none;
}
.mnav-search-inp {
  border: 0;
  outline: 0;
  background: transparent;
  width: 100%;
  font-family: "Quicksand", sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: var(--n);
}
.mnav-links {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 10px;
  align-items: center;
  text-align: center;
}
.mnav-links a {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 18px;
  border-radius: 999px;
  font-family: "Quicksand", sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.78);
  transition:
    background 0.2s,
    color 0.2s;
  width: min(280px, 100%);
}
.mnav-links a:hover,
.mnav-links a.act {
  background: rgba(var(--g-rgb), 0.16);
  color: var(--n);
}
.mnav-cta {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 16px;
  border-radius: 16px;
  background: var(--g);
  color: var(--n);
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

@media (min-width: 1101px) {
  .mnav,
  .mnav-backdrop {
    display: none !important;
  }
}

/* ═══════════════ PAGE SYSTEM ═══════════════ */
.page {
  display: none;
}
.page.active {
  display: block;
}

/* ═══════════════ SHARED ═══════════════ */
.eb {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 18px;
}
.eb-line {
  width: 36px;
  height: 1px;
  background: var(--g);
  flex-shrink: 0;
}
.eb-t {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--g);
}
.stitle {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(36px, 5vw, 68px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--n);
}
.stitle.wh {
  color: var(--w);
}
.stitle .th {
  font-weight: 200;
}
.sec {
  padding: 140px 64px;
}
/* Reveal animations */
.rv {
  opacity: 0;
  transform: translateY(44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}
.rv.on {
  opacity: 1;
  transform: none;
}
.rvl {
  opacity: 0;
  transform: translateX(-44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}
.rvl.on {
  opacity: 1;
  transform: none;
}
.rvr {
  opacity: 0;
  transform: translateX(44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}
.rvr.on {
  opacity: 1;
  transform: none;
}
.rvs {
  opacity: 0;
  transform: scale(0.94);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}
.rvs.on {
  opacity: 1;
  transform: scale(1);
}
[data-d="1"] {
  transition-delay: 0.1s;
}
[data-d="2"] {
  transition-delay: 0.2s;
}
[data-d="3"] {
  transition-delay: 0.3s;
}
[data-d="4"] {
  transition-delay: 0.4s;
}
[data-d="5"] {
  transition-delay: 0.5s;
}
[data-d="6"] {
  transition-delay: 0.6s;
}

/* Buttons */
.mbtn {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 17px 46px;
  cursor: none;
  transition: transform 0.15s;
}
.mbtn-bg {
  position: absolute;
  inset: 0;
  background: var(--g);
  transition: transform 0.45s var(--ease);
}
.mbtn:hover .mbtn-bg {
  transform: scale(1.07);
}
.mbtn-lbl {
  position: relative;
  z-index: 1;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--n);
  white-space: nowrap;
}
.mbtn.dk .mbtn-bg {
  background: var(--n);
}
.mbtn.dk .mbtn-lbl {
  color: var(--w);
}
.gbtn {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.65);
  transition:
    color 0.3s,
    gap 0.4s var(--ease);
  cursor: none;
}
.gbtn .gl {
  width: 36px;
  height: 1px;
  background: currentColor;
  transition: width 0.45s var(--ease);
}
.gbtn:hover {
  color: var(--g);
  gap: 22px;
}
.gbtn:hover .gl {
  width: 60px;
}
.gbtn.dark {
  color: rgba(var(--n-rgb), 0.5);
}
.gbtn.dark:hover {
  color: var(--g);
}

/* Marquee */
.mqw {
  overflow: hidden;
  background: var(--g);
  padding: 22px 0;
}
.mqt {
  display: flex;
  gap: 52px;
  white-space: nowrap;
  animation: mqs 26s linear infinite;
  width: max-content;
}
.mqi {
  font-family: "League Spartan", sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--n);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 26px;
}
.mqd {
  width: 4px;
  height: 4px;
  background: var(--n);
  border-radius: 50%;
  opacity: 0.3;
}
@keyframes mqs {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Page hero (inner pages) */
.ph {
  position: relative;
  height: 72vh;
  min-height: 520px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}
.ph-pbg {
  position: absolute;
  inset: -20%;
  background-size: cover;
  background-position: center;
  will-change: transform;
}
.ph-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    110deg,
    rgba(var(--n-rgb), 0.92) 0%,
    rgba(var(--n-rgb), 0.6) 60%,
    rgba(var(--n-rgb), 0.25) 100%
  );
}
.ph-body {
  position: relative;
  z-index: 2;
  padding: 0 64px 80px;
  max-width: 800px;
}
.ph-tag {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 28px;
}
.ph-tag-line {
  width: 40px;
  height: 1px;
  background: var(--g);
}
.ph-tag span {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: var(--g);
}
.ph-title {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(52px, 8vw, 100px);
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: -0.025em;
  color: var(--w);
  margin-bottom: 24px;
}
.ph-title .gold {
  color: var(--g);
}
.ph-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.75);
  max-width: 420px;
}

/* ═══════════════ HOME — HERO ═══════════════ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding-top: 110px;
}
/* Parallax layers */
.p-layer {
  position: absolute;
  will-change: transform;
}
.hero-bg-img {
  inset: -25%;
  background: url("data:image/png;base64,")
    center/cover no-repeat;
}
.hero-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(var(--n-rgb), 0.93) 0%,
    rgba(var(--n-rgb), 0.62) 52%,
    rgba(var(--n-rgb), 0.28) 100%
  );
}
/* subtle floating gradient orb */
.hero-orb {
  position: absolute;
  top: 10%;
  right: 5%;
  width: 45vw;
  height: 80vh;
  background: radial-gradient(
    ellipse at 60% 40%,
    rgba(var(--g-rgb), 0.1) 0%,
    transparent 70%
  );
  pointer-events: none;
}

.hero-body {
  position: relative;
  z-index: 2;
  padding: 0 64px;
  max-width: 100%;
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 40px;
}
.hero-body > .col-md-6 {
  flex: 1;
  min-width: 0;
}
.hero-body > .col-md-6:last-child {
  margin-top: 0;
}
.h-tag {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 36px;
  color: var(--g);
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  opacity: 0;
  animation: fu 0.8s 0.2s var(--ease) forwards;
}
.h-tag-line {
  width: 44px;
  height: 1px;
  background: var(--g);
}
.hero h1 {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(56px, 8vw, 85px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.025em;
  color: var(--w);
  margin-bottom: 36px;
}
.hero h1 .line {
  display: block;
  overflow: hidden;
}
.hero h1 .li {
  display: block;
  opacity: 0;
  transform: translateY(110%);
  animation: lu 0.95s var(--ease) forwards;
}
.l1 .li {
  animation-delay: 0.38s;
}
.l2 .li {
  animation-delay: 0.54s;
}
.l3 .li {
  animation-delay: 0.7s;
}
.hero h1 .gold {
  color: var(--g);
}
.hero-sub {
  font-size: 17px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.78);
  max-width: 440px;
  margin-bottom: 52px;
  opacity: 0;
  animation: fu 0.8s 0.9s var(--ease) forwards;
}
.hero-acts {
  display: flex;
  gap: 22px;
  align-items: center;
  flex-wrap: wrap;
  opacity: 0;
  animation: fu 0.8s 1.05s var(--ease) forwards;
}

/* Hero Form Styles */
.hero-form {
  background: rgba(var(--n-rgb), 0.4);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 40px;
  opacity: 0;
  animation: fu 0.8s 1.05s var(--ease) forwards;
  margin: 0;
  height: fit-content;
}
.hero-form-title {
  font-family: "League Spartan", sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 12px;
}
.hero-form-sub {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 10px;
}
.hero-form-fields {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.hero-form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.hero-form-lbl {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.8);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.hero-form-inp {
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: var(--w);
  font-family: "Quicksand", sans-serif;
  font-size: 14px;
  transition: all 0.3s ease;
}
.hero-form-inp::placeholder {
  color: rgba(255, 255, 255, 0.4);
}
.hero-form-inp:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(221, 168, 81, 0.5);
  box-shadow: 0 0 0 3px rgba(221, 168, 81, 0.1);
}
.hero-notice {
  min-height: 0px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.7);
}

.hero-scroll {
  position: absolute;
  bottom: 48px;
  left: 64px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  opacity: 0;
  animation: fu 0.8s 1.3s forwards;
}
.hs-bar {
  width: 1px;
  height: 64px;
  background: rgba(var(--g-rgb), 0.2);
  position: relative;
  overflow: hidden;
}
.hs-bar::after {
  content: "";
  position: absolute;
  top: -100%;
  left: 0;
  width: 1px;
  height: 45%;
  background: var(--g);
  animation: pip 2.2s var(--ease) infinite;
}
.hs-lbl {
  font-family: "Quicksand", sans-serif;
