  background-size: cover;
  background-position: center;
  will-change: transform;
  transition: transform 0.1s linear;
}
.pgcard:hover .pgcard-inner {
  transform: scale(1.03) !important;
}
.pgcard-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(var(--n-rgb), 0.9) 0%,
    rgba(var(--n-rgb), 0.05) 50%,
    transparent 100%
  );
}
.pgcard-info {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 28px 26px;
  transform: translateY(10px);
  transition: transform 0.5s var(--ease);
}
.pgcard:hover .pgcard-info {
  transform: none;
}
.pgcard-cat {
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 6px;
}
.pgcard-name {
  font-family: "League Spartan", sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 3px;
}
.pgcard-loc {
  font-size: 12px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
}

/* ═══════════════ CONTACT PAGE ═══════════════ */
.ct-body {
  background: var(--w);
  padding: 100px 64px 130px;
}
.ct-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
}
.ct-ways {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: rgba(var(--n-rgb), 0.07);
}
.ct-way {
