  height: 44px;
  background: var(--g);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.ct-way-icon svg {
  width: 20px;
  height: 20px;
  stroke: var(--n);
  fill: none;
}
.ct-way-h {
  font-family: "League Spartan", sans-serif;
  font-size: 16px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--n);
  margin-bottom: 5px;
}
.ct-way-v {
  font-size: 14px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.55);
}
.ct-way-v a {
  color: var(--g);
  font-weight: 700;
}
.ct-ec {
  background: var(--n);
  padding: 40px 44px;
  margin-top: 22px;
}
.ctec-lbl {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 16px;
}
.ctec-h {
  font-family: "League Spartan", sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 8px;
}
.ctec-addr {
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
