}
.ctec-hours {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ctec-hr {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.38);
}
.ctec-hr span:last-child {
  color: rgba(255, 255, 255, 0.65);
}
.ct-form-wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.ct-form-title {
  font-family: "League Spartan", sans-serif;
  font-size: 28px;
  font-weight: 700;
