}
.ct-form-sub {
  font-size: 14px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.5);
  line-height: 1.7;
  margin-top: -12px;
}
form.jf {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.jf-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.jf-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.jf-lbl {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
