}
.map-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 14px;
}
.map-content h3 {
  font-family: "League Spartan", sans-serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--n);
}
.map-content p {
  font-size: 14px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.5);
}
.map-badge {
  background: var(--g);
  padding: 10px 26px;
  display: inline-flex;
  margin-top: 6px;
}
.map-badge span {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--n);
}

/* ═══════════════ CRM DASHBOARD ═══════════════ */
#crm-page {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 9990;
  background: var(--gr);
  overflow-y: auto;
}
.crm-nav {
  background: var(--n);
  padding: 18px 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 10;
}
.crm-logo {
  font-family: "League Spartan", sans-serif;
  font-size: 18px;
  font-weight: 800;
  color: var(--w);
  letter-spacing: 0.05em;
}
.crm-logo .dot {
  color: var(--g);
}
.crm-close {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.08);
  border: none;
  padding: 10px 22px;
  cursor: pointer;
  transition: background 0.3s;
}
.crm-close:hover {
  background: rgba(255, 255, 255, 0.15);
}
.crm-body {
  padding: 40px;
}
.crm-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 32px;
}
.crm-stat {
  background: var(--w);
  padding: 28px 24px;
}
.crm-stat-n {
  font-family: "League Spartan", sans-serif;
  font-size: 42px;
  font-weight: 900;
  color: var(--n);
  line-height: 1;
  display: block;
}
.crm-stat-l {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.4);
  display: block;
  margin-top: 4px;
}
.crm-stat.gold-card {
  background: var(--g);
}
.crm-stat.gold-card .crm-stat-n,
.crm-stat.gold-card .crm-stat-l {
  color: var(--n);
}
.crm-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.crm-filter {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 9px 20px;
  border: 1.5px solid rgba(var(--n-rgb), 0.15);
  background: var(--w);
  color: rgba(var(--n-rgb), 0.5);
  cursor: pointer;
  transition: all 0.3s;
}
.crm-filter.act,
.crm-filter:hover {
  background: var(--n);
  border-color: var(--n);
  color: var(--w);
}
.crm-export {
  margin-left: auto;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 9px 22px;
  background: var(--g);
  border: none;
  color: var(--n);
  cursor: pointer;
  transition: opacity 0.3s;
}
.crm-export:hover {
  opacity: 0.85;
}
.crm-table-wrap {
  background: var(--w);
  overflow-x: auto;
}
table.crm-table {
  width: 100%;
  border-collapse: collapse;
  font-family: "Quicksand", sans-serif;
}
.crm-table th {
  background: var(--n);
  color: rgba(255, 255, 255, 0.7);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  padding: 14px 18px;
  text-align: left;
  white-space: nowrap;
}
.crm-table td {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(var(--n-rgb), 0.06);
  font-size: 13px;
  font-weight: 500;
  color: var(--n);
  vertical-align: middle;
}
.crm-table tr:last-child td {
  border-bottom: none;
}
.crm-table tr:hover td {
  background: rgba(var(--g-rgb), 0.04);
}
.crm-badge {
  display: inline-block;
  padding: 4px 12px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.crm-badge.new {
  background: rgba(var(--g-rgb), 0.15);
  color: #8a6520;
}
.crm-badge.contacted {
  background: rgba(25, 43, 69, 0.1);
  color: var(--n);
}
.crm-badge.qualified {
  background: rgba(39, 174, 96, 0.12);
  color: #1e8449;
}
.crm-badge.lost {
  background: rgba(192, 57, 43, 0.1);
  color: #c0392b;
}
.crm-sel {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  padding: 5px 10px;
  border: 1px solid rgba(var(--n-rgb), 0.15);
  background: var(--w);
  color: var(--n);
  cursor: pointer;
}
.crm-empty {
  text-align: center;
  padding: 60px;
  color: rgba(var(--n-rgb), 0.35);
  font-size: 15px;
  font-weight: 500;
}

/* ═══════════════ FOOTER ═══════════════ */
footer {
  background: var(--n);
}
.fg {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 60px;
  padding: 80px 64px 60px;
}
.fgm {
  font-family: "League Spartan", sans-serif;
  font-size: 40px;
  font-weight: 900;
  color: var(--w);
  letter-spacing: 0.04em;
  margin-bottom: 4px;
  display: block;
}
.fgm-dot {
  color: var(white);
}
.fgs {
  font-family: "Quicksand", sans-serif;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.22);
  margin-bottom: 22px;
  display: block;
}
.fga {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.3);
