.fg-col ul a:hover {
  color: var(--g);
  padding-left: 6px;
}
.fb {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: 22px 64px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.fb-copy {
  font-size: 11px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.15);
}
.fb-soc {
  display: flex;
  gap: 22px;
}
.fb-soc a {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.18);
  transition: color 0.3s;
}
.fb-soc a:hover {
  color: var(--g);
}

/* ═══════════════ RESPONSIVE ═══════════════ */
@media (max-width: 1100px) {
  nav,
  nav.stuck {
    padding: 18px 28px;
  }
  .nav-links,
  .ncta {
    display: none;
  }
  .ham {
    display: flex;
  }
  .sec,
  .ao,
  .hvh,
  .values,
  .founder,
  .craft,
  .exp-sec,
  .svc-intro,
  .svc-why,
  .proc-intro,
  .proc-steps,
  .ct-body,
  .testi,
  .hcta,
  .philosophy,
  .home-proj {
    padding: 80px 28px;
  }
  .home-proj {
    padding: 80px 0;
  }
  .hp-head {
    padding: 0 28px;
  }
  .ptrack {
    padding: 0 28px;
  }
  .pcard {
    flex: 0 0 300px;
    height: 420px;
  }
  .phil-grid,
  .ao-grid,
  .craft-grid,
  .exp-grid,
  .founder-grid,
  .ct-grid,
  .svc-intro-grid,
  .story-split,
  .hvh-split {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .story-split {
    grid-template-columns: 1fr;
  }
  .ss-img {
    height: 360px;
    position: relative;
  }
  .ss-img-inner {
    position: absolute;
    inset: 0;
  }
  .ao-images,
  .craft-images {
    height: 360px;
  }
  .ci-accent,
  .ao-accent {
    display: none;
  }
  .svc-item {
    grid-template-columns: 1fr;
  }
  .svc-item:nth-child(even) .si-img,
  .svc-item:nth-child(even) .si-copy {
    order: unset;
  }
  .si-img {
    height: 320px;
    position: relative;
  }
  .si-img-inner {
    position: absolute;
    inset: 0;
  }
  .sw-grid,
  .pg-grid {
    grid-template-columns: 1fr 1fr;
  }
  .val-grid,
  .tgrid {
    grid-template-columns: 1fr;
  }
  .pg {
    grid-template-columns: 1fr 1fr;
  }
  .pgcard.wide {
    grid-column: span 2;
  }
  .proc-steps {
    padding: 40px 28px 80px;
  }
  .pstep {
    grid-template-columns: 1fr;
    gap: 22px;
  }
  .pstep-dets {
    grid-template-columns: 1fr;
  }
  .proc-guar {
    padding: 60px 28px;
  }
  .pg-grid {
    grid-template-columns: 1fr 1fr;
  }
  .fg {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    padding: 56px 28px 40px;
  }
  .fb {
    padding: 20px 28px;
    flex-direction: column;
    gap: 12px;
  }
  .pf-bar,
  .pgrid {
    padding-left: 28px;
    padding-right: 28px;
  }
  .crm-stats {
    grid-template-columns: 1fr 1fr;
  }
  .crm-body {
    padding: 24px 20px;
  }
  .hvh-col {
    padding: 52px 36px;
  }
  .hvh-cta {
    padding: 60px 28px 0;
  }
  .qb-body {
    padding: 0 32px;
  }
  .exp-tag {
    bottom: -16px;
    left: -16px;
  }
  .ph-body {
    padding: 0 28px 64px;
  }
  .jf-row {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .fg {
    grid-template-columns: 1fr;
  }
  .pg {
    grid-template-columns: 1fr;
  }
  .pgcard.wide {
    grid-column: span 1;
    aspect-ratio: 3/4;
  }
  .hero h1 {
    font-size: clamp(44px, 14vw, 72px);
  }
  .sw-grid {
    grid-template-columns: 1fr;
  }
  .pg-grid {
    grid-template-columns: 1fr 1fr;
  }
  .crm-stats {
    grid-template-columns: 1fr 1fr;
  }
}

/* Additional responsive fixes for hero/form/strip overlap */
@media (max-width: 1200px) and (min-width: 993px) {
  .hero-body {
    padding-bottom: 140px; /* leave space for hero-strip */
  }
  .hero-form {
    max-width: 520px;
    margin-left: auto; /* keep form to the right */
    position: relative;
    z-index: 6; /* ensure form sits above background but below nav */
  }
  .hero-strip {
    bottom: -8px; /* nudge numbers down slightly to avoid overlap */
    right: 24px;
    z-index: 3;
  }
}

@media (max-width: 992px) and (min-width: 771px) {
  /* Slightly increase heading and add padding so form doesn't intrude */
  .hero h1 {
    font-size: clamp(44px, 8.5vw, 78px);
  }
  .hero-body {
    padding-bottom: 120px;
  }
  .hero-form {
    max-width: 520px;
    margin-left: auto;
    position: relative;
    z-index: 6;
    padding: 28px 32px;
  }
  .hero-strip {
    bottom: -10px;
    z-index: 3;
  }
}

@media (max-width: 770px) {
  /* Mobile: stack content, keep form above numbers and add bottom spacing */
  .hero-body {
    flex-direction: column;
    align-items: center;
    padding-bottom: 220px; /* ensure hero-strip sits below stacked content */
    gap: 28px;
  }
  /* .hero h1 {
    font-size: clamp(28px, 8.5vw, 60px);
  } */
  .hero-form {
    width: 100%;
    max-width: 720px;
    margin: 0 auto;
    position: relative;
    z-index: 8; /* bring form above numbers */
    padding: 20px;
  }
  .hero-strip {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    justify-content: center;
    z-index: 2; /* numbers sit below form */
  }
}

